//! `ShadowMapShader` receive derivation against the exhaustive pinned
//! CesiumJS cases in `tests/data/scene-shadow-map-shader.json` (generated by
//! `tools/cesium/generate-scene-shadow-map-shader.mjs`).

use cesium_rs::renderer::ShaderSource;
use cesium_rs::scene::shadow_map_shader::{
    receive_fragment, receive_shader_keyword, receive_vertex, ReceiveBias, ReceiveOptions,
};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("data/scene-shadow-map-shader.json")).unwrap()
}

/// The generator's three-bit bias encoding.
fn bias(bits: u64) -> ReceiveBias {
    ReceiveBias {
        normal_shading: bits & 1 != 0,
        normal_shading_smooth: if bits & 2 != 0 { 0.1 } else { 0.0 },
        normal_offset: bits & 4 != 0,
    }
}

/// 64-bit FNV-1a over `JSON.stringify(sources)`.
fn hash_sources(sources: &[String]) -> String {
    let encoded = serde_json::to_string(sources).unwrap();
    format!("{:x}", encoded.bytes().fold(0xcbf29ce484222325u64, |h, b| (h ^ u64::from(b)).wrapping_mul(0x100000001b3)))
}

#[test]
fn receive_fragment_matches_every_reference_combination() {
    let fixture = fixture();
    let cases = fixture["receive"].as_array().unwrap();
    assert_eq!(cases.len(), 4096);
    let mut keywords = 0;
    for case in cases {
        let flags = case["flags"].as_u64().unwrap();
        let layout = case["layout"].as_u64().unwrap();
        let bit = |b: u32| flags & (1 << b) != 0;
        let biases = &case["biases"];
        let options = ReceiveOptions {
            uses_depth_texture: bit(0),
            polygon_offset_supported: bit(1),
            point_light: bit(2),
            spot_light: bit(3),
            number_of_cascades: if bit(4) { 4 } else { 1 },
            debug_cascade_colors: bit(5),
            soft_shadows: bit(6),
            cast_shadows: bit(7),
            terrain: bit(8),
            terrain_normal: bit(9),
            point_bias: bias(biases["point"].as_u64().unwrap()),
            terrain_bias: bias(biases["terrain"].as_u64().unwrap()),
            primitive_bias: bias(biases["primitive"].as_u64().unwrap()),
        };
        let fs = ShaderSource {
            defines: vec!["EXISTING".into()],
            sources: vec![format!(
                "{}{}void main() {{ out_FragColor = vec4(1.0); }}",
                if layout & 1 != 0 { "in vec3 v_positionEC;" } else { "" },
                if layout & 2 != 0 { "in vec3 v_normalEC;" } else { "" }
            )],
            ..Default::default()
        };
        let result = receive_fragment(&fs, &options);
        assert_eq!(serde_json::json!(result.defines), case["defines"], "flags {flags} layout {layout}");
        assert_eq!(hash_sources(&result.sources), case["hash"].as_str().unwrap(), "flags {flags} layout {layout}");
        if let Some(keyword) = case.get("keyword") {
            assert_eq!(receive_shader_keyword(&options), keyword.as_str().unwrap(), "flags {flags}");
            keywords += 1;
        }
    }
    assert_eq!(keywords, 1024);
}

#[test]
fn receive_vertex_matches_reference() {
    let fixture = fixture();
    for case in fixture["receiveVertex"].as_array().unwrap() {
        let mask = case["mask"].as_u64().unwrap();
        let vs = ShaderSource {
            defines: vec!["EXISTING".into()],
            sources: vec!["void main() {}".into(), "float extra;".into()],
            ..Default::default()
        };
        let result = receive_vertex(&vs, mask & 1 != 0, mask & 2 != 0);
        assert_eq!(serde_json::json!(result.defines), case["defines"], "mask {mask}");
        assert_eq!(serde_json::json!(result.sources), case["sources"], "mask {mask}");
    }
}

#[test]
fn bias_selection_prefers_point_then_terrain_then_primitive() {
    let (point, terrain, primitive) = (bias(1), bias(2), bias(4));
    let options = |point_light, is_terrain| ReceiveOptions {
        point_light,
        terrain: is_terrain,
        point_bias: point,
        terrain_bias: terrain,
        primitive_bias: primitive,
        ..Default::default()
    };
    assert_eq!(options(true, true).bias(), point);
    assert_eq!(options(false, true).bias(), terrain);
    assert_eq!(options(false, false).bias(), primitive);
}
